import { cleanupOutdatedCaches, precacheAndRoute } from "workbox-precaching"
import { clientsClaim } from "workbox-core"

import { initializeApp } from "firebase/app"
import { getMessaging, onBackgroundMessage } from "firebase/messaging/sw"

// The app's scripts and styles (generated by Vite), so the app opens without a connection. The worker is served
// from /techy-sw.js, so entries the build left relative (the icon, the web manifest) are made absolute here.
const BASE = "/assets/projectit/projectit/"
precacheAndRoute(
	self.__WB_MANIFEST.map((entry) => (entry.url.startsWith("/") ? entry : { ...entry, url: BASE + entry.url }))
)

// Clean up old caches
cleanupOutdatedCaches()

// Offline: the app page and the photos people have looked at -------------------------------------------------
// Served from /techy-sw.js with scope /techy-app/. Data (jobs, chat) is kept by the app itself in IndexedDB.
const SHELL_CACHE = "techy-shell-v1"
const PHOTO_CACHE = "techy-photos-v1"
const MAX_PHOTOS = 300

async function appPage(request) {
	try {
		const response = await fetch(request)
		// Keep the latest app page (it is the same for every /techy-app route), unless we were sent to log in.
		if (response.ok && new URL(response.url).pathname.startsWith("/techy-app")) {
			const cache = await caches.open(SHELL_CACHE)
			await cache.put("/techy-app", response.clone())
		}
		return response
	} catch (e) {
		const cached = await caches.match("/techy-app", { cacheName: SHELL_CACHE })
		if (cached) return cached
		throw e
	}
}

async function photo(request) {
	const cache = await caches.open(PHOTO_CACHE)
	const cached = await cache.match(request)
	if (cached) return cached
	const response = await fetch(request)
	if (response.ok && (response.headers.get("content-type") || "").startsWith("image/")) {
		await cache.put(request, response.clone())
		const keys = await cache.keys()
		for (const old of keys.slice(0, Math.max(0, keys.length - MAX_PHOTOS))) await cache.delete(old)
	}
	return response
}

self.addEventListener("fetch", (event) => {
	const { request } = event
	if (request.method !== "GET") return
	const url = new URL(request.url)
	if (url.origin !== self.location.origin) return
	if (request.mode === "navigate" && url.pathname.startsWith("/techy-app")) {
		event.respondWith(appPage(request))
	} else if (request.destination === "image" && /^\/(private\/)?files\//.test(url.pathname)) {
		event.respondWith(photo(request))
	}
})

// Phone notifications (Web Push) -----------------------------------------------------------------------------
// The site sends an empty push; ask it what is new and show that. Each notification is tagged with its name, so
// one already on screen is replaced quietly rather than shown twice. See projectit/push.py.
const ICON = "/assets/projectit/projectit/icons/icon-192.png"
// Android shows the badge in the status bar using only its shape: white on transparent.
const BADGE = "/assets/projectit/projectit/icons/badge-96.png"

self.addEventListener("push", (event) => {
	event.waitUntil(
		(async () => {
			let items = []
			try {
				const response = await fetch("/api/method/projectit.push.pending", { credentials: "include", headers: { Accept: "application/json" } })
				if (response.ok) items = (await response.json()).message || []
			} catch (e) {
				/* offline or signed out: fall back to a plain alert */
			}
			if (!items.length) {
				// Browsers expect every push to show something.
				return self.registration.showNotification("Techy Ops", { body: "You have new notifications.", tag: "techy-push", icon: ICON, badge: BADGE, data: { url: "/techy-app/home" } })
			}
			for (const n of items.reverse()) {
				await self.registration.showNotification(n.title, { body: n.body, tag: `techy-${n.tag}`, icon: ICON, badge: BADGE, data: { url: n.url } })
			}
		})()
	)
})

self.addEventListener("notificationclick", (event) => {
	const url = event.notification.data && event.notification.data.url
	if (!url || !url.startsWith("/techy-app")) return
	event.notification.close()
	event.waitUntil(
		(async () => {
			const open = await clients.matchAll({ type: "window", includeUncontrolled: true })
			const win = open.find((w) => new URL(w.url).pathname.startsWith("/techy-app"))
			if (win) {
				await win.focus()
				return win.navigate(url).catch(() => clients.openWindow(url))
			}
			return clients.openWindow(url)
		})()
	)
})

const jsonConfig = new URL(location).searchParams.get("config")

// Firebase config initialization
try {
	const firebaseApp = initializeApp(JSON.parse(jsonConfig))
	const messaging = getMessaging(firebaseApp)

	function isChrome() {
		return navigator.userAgent.toLowerCase().includes("chrome")
	}

	onBackgroundMessage(messaging, (payload) => {
		const notificationTitle = payload.data.title
		let notificationOptions = {
			body: payload.data.body || "",
		}
		if (payload.data.notification_icon) {
			notificationOptions["icon"] = payload.data.notification_icon
		}
		if (isChrome()) {
			notificationOptions["data"] = {
				url: payload.data.click_action,
			}
		} else {
			if (payload.data.click_action) {
				notificationOptions["actions"] = [
					{
						action: payload.data.click_action,
						title: "View Details",
					},
				]
			}
		}
		self.registration.showNotification(notificationTitle, notificationOptions)
	})

	if (isChrome()) {
		self.addEventListener("notificationclick", (event) => {
			event.stopImmediatePropagation()
			event.notification.close()
			if (event.notification.data && event.notification.data.url) {
				clients.openWindow(event.notification.data.url)
			}
		})
	}
} catch (error) {
	// No push configuration on this site: offline support still works.
}

self.skipWaiting()
clientsClaim()
